def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = DAILY_SALARY * 0.22
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.55
        return max(0.0, min(budget, base))

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units < 1.15:
        scarcity = 2
    elif units < 1.8:
        scarcity = 1

    prev_bids = []
    pressure_bids = []
    stressed_count = 0
    rich_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            adj = float(bid)
            if opp.get('budget', 0) < 120:
                adj *= 0.75
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
                adj *= 1.12
            pressure_bids.append(adj)
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2 or opp.get('budget', 0) < 100:
            stressed_count += 1
        if opp.get('budget', 0) > 300:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_pressure = max(pressure_bids) if pressure_bids else 0.0

    if scarcity == 2:
        target = max(DAILY_SALARY * 0.92, highest_pressure + 2.0)
    elif scarcity == 1:
        target = max(DAILY_SALARY * 0.52, highest_pressure * 0.72 + 1.0)
    else:
        target = DAILY_SALARY * 0.26
        if highest_prev > 0:
            target = max(target, min(DAILY_SALARY * 0.48, highest_pressure * 0.5))

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water_days >= 1:
        target = max(target, DAILY_SALARY * 0.72)

    if stressed_count >= len(alive):
        target *= 0.9
    elif rich_count >= 2 and scarcity >= 1:
        target *= 1.08

    if day >= 8 and hp >= 6 and scarcity == 0:
        target *= 0.88

    if budget < DAILY_SALARY:
        target = min(target, budget * 0.92)
    elif budget < DAILY_SALARY * 2:
        target = min(target, DAILY_SALARY * 0.78)

    if target < 0:
        target = 0.0
    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    total_water_needed = WATER_REQ
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    base_bid = DAILY_SALARY * 0.5

    if current_supply < total_water_needed * 0.8:
        base_bid *= 1.4
    elif current_supply < total_water_needed * 1.2:
        base_bid *= 1.15
    else:
        base_bid *= 0.8

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 1.05
    elif my_hp <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif my_hp >= 8:
        base_bid *= 0.85

    day_aggression_factor = 1 + (current_day / EPISODE_DAYS) * 0.2
    base_bid *= day_aggression_factor

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if max_yesterday_bid >= DAILY_SALARY * 0.8:
            if my_hp <= 4:
                base_bid = max(base_bid, max_yesterday_bid * 1.05)
            else:
                base_bid = max(base_bid, max_yesterday_bid * 1.01)
        elif max_yesterday_bid <= DAILY_SALARY * 0.3:
            base_bid = min(base_bid, max_yesterday_bid * 0.9)
        else:
            base_bid = max(base_bid, avg_yesterday_bid * 1.02)

    final_bid = max(1.0, min(base_bid, my_budget))

    if my_hp <= 1:
        final_bid = min(my_budget, max(final_bid, DAILY_SALARY * 1.1))
    elif my_hp <= 3:
        final_bid = min(my_budget, max(final_bid, DAILY_SALARY * 0.95))

    return round(final_bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else DAILY_SALARY * 0.6
    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.1)
    if day_context['supply'] < WATER_REQ * 2:
        return min(my_status['budget'], avg_prev * 1.05)
    return min(my_status['budget'], avg_prev * 0.95)
